const canvas=document.querySelector('#orb');const ctx=canvas.getContext('2d');let pointer={x:.15,y:-.1},target={...pointer},time=0;
function resize(){const d=Math.min(devicePixelRatio,2),r=canvas.getBoundingClientRect();canvas.width=r.width*d;canvas.height=r.height*d;ctx.setTransform(d,0,0,d,0,0)}
function point3(x,y,z,rx,ry,cx,cy,scale){let cyy=Math.cos(ry),sy=Math.sin(ry),cxx=Math.cos(rx),sx=Math.sin(rx);let x1=x*cyy-z*sy,z1=x*sy+z*cyy,y1=y*cxx-z1*sx,z2=y*sx+z1*cxx;let p=scale/(scale+z2);return{x:cx+x1*p,y:cy+y1*p,z:z2,p}}
function draw(){const w=canvas.clientWidth,h=canvas.clientHeight;ctx.clearRect(0,0,w,h);target.x+=(pointer.x-target.x)*.04;target.y+=(pointer.y-target.y)*.04;time+=.006;const cx=w*.52,cy=h*.5,r=Math.min(w,h)*.3,pts=[];for(let a=0;a<Math.PI*2;a+=Math.PI/18){for(let b=0;b<Math.PI*2;b+=Math.PI/24){let swell=1+.14*Math.sin(3*a+time*5)*Math.cos(2*b-time*3);let x=Math.cos(a)*(1.05+.27*Math.cos(b))*r*swell;let y=Math.sin(b)*r*.5;let z=Math.sin(a)*(1.05+.27*Math.cos(b))*r*swell;pts.push(point3(x,y,z,target.y*.7,target.x+time,cx,cy,r*3))}}pts.sort((a,b)=>a.z-b.z);for(const p of pts){const alpha=Math.max(.08,.72-(p.z/r)*.3);ctx.beginPath();ctx.arc(p.x,p.y,Math.max(.7,2.1*p.p),0,Math.PI*2);ctx.fillStyle=`rgba(255,${90+Math.max(0,p.z/r)*55},${58+Math.max(0,p.z/r)*30},${alpha})`;ctx.fill()}ctx.beginPath();ctx.arc(cx,cy,r*.38,0,Math.PI*2);const g=ctx.createRadialGradient(cx-r*.1,cy-r*.1,0,cx,cy,r*.4);g.addColorStop(0,'rgba(255,210,190,.28)');g.addColorStop(.45,'rgba(255,91,61,.12)');g.addColorStop(1,'rgba(255,91,61,0)');ctx.fillStyle=g;ctx.fill();requestAnimationFrame(draw)}
canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();pointer.x=(e.clientX-r.left)/r.width*2-1;pointer.y=(e.clientY-r.top)/r.height*2-1});canvas.addEventListener('pointerleave',()=>pointer={x:.15,y:-.1});window.addEventListener('resize',resize);resize();if(!matchMedia('(prefers-reduced-motion: reduce)').matches)draw();else{pointer={x:.1,y:-.1};draw()}
const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>io.observe(el));
